/** Merge bhcdata data with LMI haircut data **/
/** The data and code for constructing "weights_y9c.dta" are obtained from Bai, Krishnamurthy, and Weymuller (2018) **/
/** "weights_y9c.dta" is provided in the code package **/
proc import out= lmiweights datafile = "...\Data\LMI\weights_y9c.dta" replace;
run;

data lmiweights;
set lmiweights;
keep date awgt_loan_ORG0 awgt_treas_ORG0 awgt_ag_ORG0 awgt_muni_ORG0 awgt_strucf_ORG0 awgt_corp_ORG0 awgt_eq_ORG0;
