	convert dfvcv_financialassets = dfvcv_financialassets_q_lag / transform= (lag 1);
	convert dfvcv_netloans = dfvcv_netloans_q_lag / transform= (lag 1);
	convert equity = equity_lag / transform= (lag 1);
	convert assets = assets_lag / transform= (lag 1);
by group_id;
id code;
