proc import datafile="&dir\%qsysfunc(dread(&did,&i))" out=dsn&cnt 
   dbms=csv replace; 
   guessingrows=max;
run;

%convert_vars_to_numeric(datasets=dsn1 dsn2 dsn3 dsn4 dsn5 dsn6 dsn7 dsn8 dsn9 dsn10 dsn11 dsn12 dsn13 dsn14 dsn15 dsn16 dsn17 dsn18 dsn19 
dsn20 dsn21 dsn22 dsn23 dsn24 dsn25 dsn26 dsn27 dsn28 dsn29, vars=escrow depsumbr	asset	depdom	depsum	INSBRDD	INSBRTS);

****Merge all datasets into one;
data sod_data.sod;
  set dsn: ;
run;

data sod2;
	set sod_data.sod;
	keep RSSDID RSSDHCR BRNUM CITY2BR CITYBR DEPDOM DEPSUM DEPSUMBR INSURED MSABR MSANAMB NAMEBR NAMEFULL STALPBR STCNTYBR UNINUMBR YEAR;
run;

proc sql; create table bhc_states as select distinct
RSSDHCR as bankid, year, count(STALPBR) as state_count
from sod3 
group by RSSDHCR, year;
quit;

data sod_data.bhc_states;
	set bhc_states;
run;

data sod_data.bhc_single_state;
	set sod_data.bhc_states;
	where state_count eq 1;
run;

proc sql; create table sod_data.bhc_single_state2 as select
a.*, b.STALPBR
from sod_data.bhc_single_state as a left join sod3 as b
on (a.bankid=b.RSSDHCR) and (a.year=b.year);
quit;

proc sql; create table bank_states as select distinct
RSSDID as bankid, year, count(STALPBR) as state_count
from sod4 
group by RSSDID, year;
quit;

data sod_data.bank_states;
	set bank_states;
run;

data sod_data.bank_single_state;
	set sod_data.bank_states;
	where state_count eq 1;
run;

proc sql; create table sod_data.bank_single_state2 as select
a.*, b.STALPBR
from sod_data.bank_single_state as a left join sod2 as b
on (a.bankid=b.RSSDID) and (a.year=b.year);
quit;

/***Stack these two datasets ***/
data states;
  set sod_data.bhc_single_state2 sod_data.bank_single_state2;
run;

proc sort data=states nodupkey dupout = dups;
      by bankid year;
run;   

data sod_data.states;
	set states;
run;

