proc sql; create table financialdata2_nofqecode as select
a.*, b.code
from financialdata2_nofqe as a left join fvdata.qtrnum as b
on (a.year=b.year) and (a.quarter=b.quarter);
quit;

data fvdata.financialdata2_nofqecode;
     set financialdata2_nofqecode;
     rename code=fcode;
