proc sql; create table financialdata2_fqecode2 as select
a.*, b.code
from financialdata2_fqecode as a left join fvdata.qtrnum as b
on (a.year=b.year) and (a.quarter=b.quarter);
quit;

data financialdata2_fqecode2;
