run;

/* Generate the final fyear and fquarter variables */
proc sql; create table financialdata2_4 as select
a.*, b.year, b.quarter
from financialdata2_3 as a left join fvdata.qtrnum as b
on (a.fcode=b.code);
quit;

data financialdata2_4;
     set financialdata2_4;
     rename year=fyear;
	 rename quarter=fquarter;
