/** Merge bhcdata data with LMI haircut data **/
/** The data and code for constructing "weights_y9c.dta" are obtained from Bai, Krishnamurthy, and Weymuller (2018) **/
/** "weights_y9c.dta" is provided in the code package **/
proc import out= lmiweights datafile = "...\Data\LMI\weights_y9c.dta" replace;
run;

data lmiweights;
set lmiweights;
keep date awgt_loan_ORG0 awgt_treas_ORG0 awgt_ag_ORG0 awgt_muni_ORG0 awgt_strucf_ORG0 awgt_corp_ORG0 awgt_eq_ORG0;
run;
proc sort data=lmiweights;
      by date;
run; 

data lmiweights2;
set lmiweights;
year = year(date);
quarter = qtr(date);
run;

proc sql; create table bhcdata12 as select
a.*, b.awgt_loan_ORG0
from bhcdata11 as a left join lmiweights2 as b
on (a.year=b.year) and (a.quarter=b.quarter);

        data &ds;
            set &ds;
            new = input(&var, ??comma20.);
			drop &var;
			rename new=&var;
        run;

/*** Merge with Quarter Reference Table (provided in the code package)  ***/
proc sql; create table bhcdata_temp as select
a.*, b.code
from bhcdata_com as a left join fvdata.qtrnum as b
on (a.year=b.year) and (a.quarter=b.quarter);
quit;

/*** Process SNL financial statement data ***/
data financialdata2;
	set fvdata.financialdata2;
   new = input(BHC_number, 11.);
   drop BHC_number;
   rename new=BHC_number;
run;

data financialdata2;
	set financialdata2;
   new = input(Federal_Reserve_ID, 11.);
   drop Federal_Reserve_ID;
   rename new=Federal_Reserve_ID;
run;

proc sort data=financialdata2; by SNLid fyear fquarter;run;
data financialdata2;
   set financialdata2;
   by SNLid fyear;
   if first.fyear then SNL_NCO_ytd=SNL_NCO;
   else SNL_NCO_ytd +  SNL_NCO;
run;

/** Transform income statement call report variables to quarterly data **/
data bhcdata_bf2013;
     set bhcdata;
where date<20140215;
run;
data bhcdata_af2014;
     set bhcdata;
where date>20140215;
run;

/*Income statement call report data for periods before 2013 are obtained from WRDS and are year-to-date. They need to be converted to quarter-to-date.*/
/*Income statement call report data for periods after 2013 are obtained from SNL and are quarter-to-date. They do not need to be converted.*/
%macro addnewlag(x);
   data bhcdata_bf2013;
    set bhcdata_bf2013;
    diff_&x = &x - lag(&x);
    if quarter =1 then diff_&x = &x;
   run;
%mend;

proc sql; create table bhcdata13 as select
a.*, b.state_count as state_count_SOD, b.STALPBR
from bhcdata12 as a left join fvdata.states as b
